	include 'all.macros'	include 'e16.locator'LMLoader	PROCTrue	equ $FFFFFalse	equ 0MyHandle	equ 0MyPointer	equ 4Ptr	equ 8TheUserID	equ $401C;-----------------------------------------------------------;; Brk if necessary;	lda >$C062	and #$0080	beq @NoBreak	brk 17@NoBreak;-----------------------------------------------------------;; Set dbr;	phk	plb;-----------------------------------------------------------;; Unload last patch;	pha	; space for result	PushWord #TheUserID	PushWord #0	_UserShutdown	pla;-----------------------------------------------------------;; Load the new one;	pha	; space for dir page stack size	pha	; space for addr of	dir page stack seg	pha	; space for starting addr	pha	pha	; space for user id	PushWord #TheUserID	; user id	PushLong #TheName	; ptr to path name	PushWord #True	_InitialLoad	bcs Die	pla	; ignore userid	pla	; put starting address	sta TableAddress	pla	sta TableAddress+2	pla	; ignore dir page	pla	; ignore dir page size;-----------------------------------------------------------;; Install;	PushWord #0	; system call	PushWord #$001C	; install the patch	PushLong TableAddress	_SetTSPtr		_SetDefaultTPT;-----------------------------------------------------------;; Quit	_Quit QuitParamsQuitParams	DC.L 0	DC.W 0TheName	str '1/tool028'TableAddress	DS.B 4Die		; 	pha	PushLong #ErrorString	_SysFailMgrErrorString	str 'Could not load.  Error was $'	ENDP	END